def base_cfg(d, sc):
    """The benchmark configuration, verbatim from cpu.akf (cov_mult = 1)."""
    sigma = max(1e-4, float(H.MJ.robust_noise_var(d.q_obs[None], d.t_obs)[0].sqrt()))
    cfg = cpu.AKFConfig(max_step_s=1 / (240 * sc["T"]), position_process_std=.1 * sigma, velocity_process_std=sigma,
                        parameter_process_std=0., position_measurement_std=sigma, initial_position_std=sigma,
                        initial_velocity_std=1., initial_parameter_std=math.log(100))
    return cfg, sigma

def native_select(d, cfg):
    """cpu.akf's native 35-start innovation-NLL selection (same bisection on non-finite batches), arbitrary configuration."""
    found = []

    def evaluate(pairs):
        try:
            r = run_akf_batched(d, [p[0] for p in pairs], [p[1] for p in pairs], cfg)
            if not bool(torch.isfinite(r.innovation_scores).all()):
                raise FloatingPointError("nonfinite innovation likelihood")
            found.extend((float(r.innovation_scores[i]), p) for i, p in enumerate(pairs))
        except (FloatingPointError, RuntimeError, ValueError, OverflowError):
            if len(pairs) > 1:
                k = len(pairs) // 2; evaluate(pairs[:k]); evaluate(pairs[k:])
    evaluate(H.grid())
    nll, best = min(found)
    return best, nll

def replay(d, I, c, q0=0.0, v0=0.0):
    """open-loop trajectory of the estimate on A (normalised units), same RK4/ZOH transition as the filter."""
    cfg = cpu.AKFConfig(max_step_s=1 / 2400)
    z = torch.tensor([q0, v0, math.log(I), math.log(c)], dtype=torch.float64)
    out = [float(z[0])]
    for i in range(1, len(d.t_obs)):
        z = _transition(d, cfg, d.t_obs[i - 1], d.t_obs[i], z); out.append(float(z[0]))
    return np.asarray(out)

def run_variant(d, sc, cfg, init=None, passes=1, q0v0=(0.0, 0.0)):
    t0 = time.perf_counter()
    if init is None:
        (I0, c0), nll = native_select(d, cfg)
    else:
        I0, c0, nll = init[0], init[1], None
    cfg = replace(cfg, inertia_guess=I0, damping_guess=c0)
    for _ in range(passes):
        r = run_akf(d, cfg, dense_t=d.t_obs[:1])
    fs = r.filtered_state
    I, c, _ = physical_parameters(fs[-1, 2], fs[-1, 3], "free_c")
    inn, var = r.innovations.numpy()[1:], r.innovation_variances.numpy()[1:]
    nis = inn ** 2 / var
    ac = float(np.corrcoef(inn[:-1], inn[1:])[0, 1])
    I, c = float(I), float(c)
    q_rep = replay(d, I, c, *q0v0)
    qo = d.q_obs.numpy()
    traj = [dict(t=float(d.t_obs[k]), I=float(torch.exp(fs[k, 2])) * sc["inertia_to_physical"],
                 c=float(torch.exp(fs[k, 3])) * sc["damping_to_physical"]) for k in range(0, len(fs), 5)]
    return dict(I=I * sc["inertia_to_physical"], c=c * sc["damping_to_physical"], I0=I0, c0=c0, nll=nll,
                nis_mean=float(nis.mean()), nis_median=float(np.median(nis)), innov_lag1=ac,
                logvar_I=float(r.filtered_covariance[-1, 2, 2]), logvar_c=float(r.filtered_covariance[-1, 3, 3]),
                filtered_q_nrmse_pct=100 * float(np.sqrt(np.mean((fs[:, 0].numpy() - qo) ** 2))),
                replay_A_nrmse_pct=100 * float(np.sqrt(np.mean((q_rep - qo) ** 2))),
                sigma_R=cfg.position_measurement_std, vel_std=cfg.velocity_process_std, par_std=cfg.parameter_process_std,
                wall_s=time.perf_counter() - t0, param_trajectory=traj)
